//! A ciphertext written before ADR 0001 opens on the new path.
//!
//! `testdata/pre-adr-0001-cross-lang.bin` is the Go binding's cross-language
//! fixture as it was generated by the `Value` path, before the sink-based
//! model: a record of passthrough fields, strings, every numeric width,
//! a null, a nested array and bytes, sealed with native AES-256-GCM. It is
//! decoded with this crate's ciphertext codec, opened through
//! `decrypt_to_frame`, and must come out as the frame the fixture carries,
//! byte for byte. That pins the leaf format, the AAD derivations and the
//! container rules against what shipped.
//!
//! Layout (all lengths u32 LE):
//! `"VCGO1" ++ key[32] ++ len(aad) ++ aad ++ len(ct) ++ ct ++ len(val) ++ val`

use vitaminc_aead::{decrypt_to_frame, Context, DecryptError, Frame, Node};
use vitaminc_aead_frame::{decode_ciphertext, Reader};
use vitaminc_encrypt::{Aes256Cipher, Key, LocalCipherText};
use vitaminc_protected::Controlled;

const FIXTURE: &[u8] = include_bytes!("../testdata/pre-adr-0001-cross-lang.bin");

struct Fixture {
    key: [u8; 32],
    aad: Vec<u8>,
    ciphertext: Vec<u8>,
    value: Vec<u8>,
}

fn fixture() -> Fixture {
    let (magic, rest) = FIXTURE.split_at(5);
    assert_eq!(magic, b"VCGO1");
    let (key, mut rest) = rest.split_at(32);
    let mut chunk = || {
        let (len, after) = rest.split_at(4);
        let len = u32::from_le_bytes(len.try_into().expect("u32")) as usize;
        let (chunk, after) = after.split_at(len);
        rest = after;
        chunk.to_vec()
    };
    let aad = chunk();
    let ciphertext = chunk();
    let value = chunk();
    assert!(rest.is_empty(), "the fixture is three chunks");
    Fixture {
        key: key.try_into().expect("32-byte key"),
        aad,
        ciphertext,
        value,
    }
}

#[test]
fn a_pre_adr_0001_ciphertext_opens_into_the_frame_it_was_sealed_from() {
    let fixture = fixture();
    let cipher = Aes256Cipher::new(&Key::from(fixture.key)).expect("cipher");
    let node: Node<LocalCipherText> =
        decode_ciphertext(&mut Reader::new(&fixture.ciphertext)).expect("decodes");
    let opened = decrypt_to_frame(&cipher, node, Context::from_encoded(fixture.aad.as_slice()))
        .expect("opens");
    assert_eq!(opened.risky_ref(), &fixture.value);
    // The fixture's value is one frame, with the passthrough fields and the
    // whole numeric family of the record it describes.
    let frame = Frame::parse(&fixture.value).expect("one frame");
    assert_eq!(frame.as_bytes().len(), fixture.value.len());
}

#[test]
fn the_fixture_still_authenticates_its_aad() {
    let fixture = fixture();
    let cipher = Aes256Cipher::new(&Key::from(fixture.key)).expect("cipher");
    let node: Node<LocalCipherText> =
        decode_ciphertext(&mut Reader::new(&fixture.ciphertext)).expect("decodes");
    let err = decrypt_to_frame(&cipher, node, Context::from_encoded(b"other".as_slice()))
        .expect_err("wrong AAD");
    assert!(matches!(err, DecryptError::Cipher(_)), "{err:?}");
}
